import json
from pathlib import Path
recipes=[
('margherita-pizza','Margherita pizza',['Italian','vegetarian','weekend'],2,[(250,'g','pizza dough'),(150,'g','tomato passata'),(125,'g','mozzarella'),(10,'g','fresh basil'),(10,'ml','olive oil')],[590,23,72,22],'1. Heat the oven to its highest setting with a baking tray inside.\n2. Stretch the dough onto baking paper. Spread with passata and torn mozzarella.\n3. Bake on the hot tray for 10–15 minutes until the base is crisp and the cheese bubbles.\n4. Finish with basil and olive oil.'),
('lemon-chickpea-bowl','Lemon & chickpea bowls',['vegetarian','quick','Mediterranean'],2,[(400,'g','cooked chickpeas'),(150,'g','couscous'),(200,'g','cucumber'),(200,'g','tomatoes'),(1,'unit','lemon'),(20,'ml','olive oil'),(50,'g','feta')],[620,24,78,22],'1. Cover couscous with boiling water following pack instructions. Rest covered, then fluff.\n2. Dice cucumber and tomatoes. Drain and rinse chickpeas.\n3. Mix lemon juice and olive oil. Toss everything together and crumble over feta.'),
('roast-salmon-potatoes','Roast salmon & new potatoes',['fish','oven','simple'],2,[(300,'g','salmon fillet'),(500,'g','potatoes'),(300,'g','broccoli'),(1,'unit','lemon'),(15,'ml','olive oil')],[650,40,48,30],'1. Heat oven to 210°C. Halve potatoes, toss with oil and roast for 25 minutes.\n2. Add salmon and broccoli to the tray. Roast for another 12–15 minutes until the fish is cooked through and potatoes are tender.\n3. Finish with lemon juice.'),
('red-lentil-dal','Coconut & red lentil dal',['vegan','batch cooking','comfort'],4,[(300,'g','red lentils'),(400,'ml','coconut milk'),(400,'g','chopped tomatoes'),(200,'g','onion'),(15,'g','ginger'),(10,'g','curry powder'),(250,'g','rice'),(15,'ml','olive oil')],[690,23,99,23],'1. Soften diced onion in oil for 8 minutes. Add grated ginger and curry powder.\n2. Add rinsed lentils, tomatoes, coconut milk and 500 ml water. Simmer for 20–25 minutes, stirring and adding water as needed.\n3. Cook rice separately according to pack instructions. Serve with the dal.'),
('chicken-pepper-traybake','Chicken & pepper traybake',['chicken','oven','weeknight'],2,[(300,'g','chicken breast'),(300,'g','bell peppers'),(400,'g','potatoes'),(150,'g','red onion'),(20,'ml','olive oil'),(5,'g','paprika')],[570,43,53,19],'1. Heat oven to 210°C. Cut potatoes into small wedges, peppers into strips and onion into wedges.\n2. Toss vegetables with oil and paprika, roast for 20 minutes.\n3. Add chicken, cut into large pieces, and roast for 20–25 minutes more until cooked through.'),
('spinach-ricotta-pasta','Spinach & ricotta pasta',['vegetarian','pasta','quick'],2,[(180,'g','pasta'),(250,'g','spinach'),(150,'g','ricotta'),(1,'unit','lemon'),(20,'g','parmesan'),(10,'ml','olive oil')],[610,28,76,22],'1. Cook pasta, reserving a mug of cooking water.\n2. Wilt spinach in olive oil in a large pan. Stir in ricotta, lemon zest and a splash of pasta water.\n3. Toss with the pasta, loosen with more cooking water and finish with parmesan.'),
('black-bean-tacos','Black bean & avocado tacos',['vegetarian','quick','Mexican'],2,[(400,'g','cooked black beans'),(6,'unit','small tortillas'),(1,'unit','avocado'),(200,'g','tomatoes'),(1,'unit','lime'),(5,'g','ground cumin')],[680,23,87,25],'1. Warm drained beans with cumin and a splash of water, then lightly mash.\n2. Dice tomatoes and avocado; toss with lime juice.\n3. Warm tortillas, spoon in beans and top with the fresh mixture.'),
('mushroom-barley-soup','Mushroom & barley soup',['vegan','batch cooking','comfort'],4,[(500,'g','mushrooms'),(200,'g','pearl barley'),(200,'g','carrots'),(200,'g','onion'),(1000,'ml','vegetable stock'),(20,'ml','olive oil')],[340,11,56,8],'1. Dice onion and carrots, slice mushrooms. Soften onion and carrots in oil for 8 minutes.\n2. Add mushrooms and cook for 5 minutes. Add barley and stock.\n3. Simmer for 35–45 minutes until barley is tender, adding water if needed.'),
('tomato-butter-beans','Tomato & butter beans',['vegetarian','one pot','quick'],2,[(400,'g','cooked butter beans'),(400,'g','chopped tomatoes'),(100,'g','onion'),(100,'g','spinach'),(80,'g','feta'),(15,'ml','olive oil'),(150,'g','bread')],[660,29,81,22],'1. Soften chopped onion in oil. Add tomatoes and simmer for 10 minutes.\n2. Add drained beans and spinach. Simmer until hot and wilted.\n3. Crumble feta over the top and serve with bread.'),
('courgette-pea-risotto','Courgette & pea risotto',['vegetarian','Italian','seasonal'],2,[(180,'g','risotto rice'),(250,'g','courgette'),(150,'g','peas'),(100,'g','onion'),(700,'ml','vegetable stock'),(30,'g','parmesan'),(15,'ml','olive oil')],[590,20,87,17],'1. Soften chopped onion and diced courgette in oil. Stir in rice for 1 minute.\n2. Add hot stock a ladle at a time, stirring until absorbed, for around 20 minutes.\n3. Add peas for the last 5 minutes. Stir in parmesan and rest for 2 minutes.')]
out=[]
for id,title,tags,servings,ingredients,nutrition,method in recipes:out.append(dict(id=id,version=0,title=title,tags=tags,servings=servings,ingredients=[dict(quantity=q,unit=u,name=n) for q,u,n in ingredients],nutrition=dict(zip(['kcal','protein_g','carbs_g','fat_g'],nutrition)),nutrition_note='Illustrative estimate per serving, not laboratory-verified.',method=method))
from french import recipe
out=[recipe(r) for r in out]
Path(__file__).with_name('seed.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
